package textmate

import (
	"bytes"
	"fmt"
	"maps"
	"slices"
	"strconv"
	"strings"

	"github.com/unstoppablemango/tdl/internal/ebnf"
)

// sublimeHeader is the sublime-syntax file's comment block.
var sublimeHeader = []string{
	"Code generated by tools/textmate from docs/grammar.ebnf. DO NOT EDIT.",
	"The same rules as editors/vscode/syntaxes/tdl.tmLanguage.json, for bat and",
	"Sublime Text, which read sublime-syntax rather than TextMate grammars.",
	"docs/architecture/editors.md says why it is derived, and docs/grammar.ebnf",
	"and lex/table.go are the files to change.",
}

// EmitSublime writes the grammar Emit writes as a sublime-syntax, which is
// what bat (through syntect) and Sublime Text read.
//
// The two formats share their semantics: each context takes the earliest
// match in the line and, on a tie, the first listed. A TextMate region
// becomes a context pushed by its begin, whose first rule is its end, since
// TextMate prefers the end on a tie; `$self` becomes `main`.
func EmitSublime(file *ebnf.File) ([]byte, error) {
	patterns, err := rules(file)
	if err != nil {
		return nil, err
	}

	w := &sublime{}
	main, err := w.items(patterns)
	if err != nil {
		return nil, err
	}
	w.contexts = append([]context{{name: "main", items: main}}, w.contexts...)

	var b bytes.Buffer
	b.WriteString("%YAML 1.2\n---\n")
	for _, line := range sublimeHeader {
		fmt.Fprintf(&b, "# %s\n", line)
	}
	fmt.Fprintf(&b, "name: %s\n", languageName)
	fmt.Fprintf(&b, "scope: %s\n", scopeName)
	b.WriteString("file_extensions:\n  - tdl\n")
	b.WriteString("contexts:\n")
	for _, c := range w.contexts {
		fmt.Fprintf(&b, "  %s:\n", c.name)
		for _, it := range c.items {
			it.write(&b)
		}
	}
	return b.Bytes(), nil
}

// A sublime collects the contexts regions push, in the order they are
// first reached.
type sublime struct {
	contexts []context
}

type context struct {
	name  string
	items []item
}

// An item is one entry of a context: a match, or an include.
type item struct {
	match    string
	scope    string
	captures map[string]string
	push     string
	set      string
	pop      bool
	include  string
}

// context reserves a context name and fills it once its items are known,
// so contexts are listed in the order their regions begin.
func (w *sublime) context(name string, fill func() ([]item, error)) (string, error) {
	name = fmt.Sprintf("%s-%d", name, len(w.contexts)+1)
	i := len(w.contexts)
	w.contexts = append(w.contexts, context{name: name})
	items, err := fill()
	if err != nil {
		return "", err
	}
	w.contexts[i].items = items
	return name, nil
}

func (w *sublime) items(rules []rule) ([]item, error) {
	var out []item
	for _, r := range rules {
		it, err := w.item(r)
		if err != nil {
			return nil, err
		}
		out = append(out, it)
	}
	return out, nil
}

func (w *sublime) item(r rule) (item, error) {
	switch {
	case r.Include == "$self":
		return item{include: "main"}, nil
	case r.Include != "":
		return item{}, fmt.Errorf("include %q: only $self has a sublime-syntax spelling", r.Include)
	case r.split != nil:
		return w.splitRegion(r)
	case r.Begin != "":
		return w.region(r)
	}

	scope, captures, err := scopes(r.Name, r.Captures)
	if err != nil {
		return item{}, err
	}
	return item{match: r.Match, scope: scope, captures: captures}, nil
}

// region is a begin pushing a context that its end pops.
func (w *sublime) region(r rule) (item, error) {
	if r.Name != "" {
		return item{}, fmt.Errorf("region %q: a named region has no sublime-syntax spelling here", r.Begin)
	}
	scope, captures, err := scopes("", r.BeginCaptures)
	if err != nil {
		return item{}, err
	}

	name, err := w.context("block", func() ([]item, error) { return w.body(r) })
	if err != nil {
		return item{}, err
	}
	return item{match: r.Begin, scope: scope, captures: captures, push: name}, nil
}

// splitRegion reads a region's begin in two contexts: one from the head
// to Open, holding the whole grammar as the patterned capture does, and
// the region's body, which Open sets in its place.
func (w *sublime) splitRegion(r rule) (item, error) {
	scope, captures, err := scopes("", r.split.HeadCaptures)
	if err != nil {
		return item{}, err
	}

	header, err := w.context("header", func() ([]item, error) {
		body, err := w.context("body", func() ([]item, error) { return w.body(r) })
		if err != nil {
			return nil, err
		}
		return []item{{match: r.split.Open, set: body}, {include: "main"}}, nil
	})
	if err != nil {
		return item{}, err
	}
	return item{match: r.split.Head, scope: scope, captures: captures, push: header}, nil
}

// body is a region's context: its end first, then its rules.
func (w *sublime) body(r rule) ([]item, error) {
	scope, captures, err := scopes("", r.EndCaptures)
	if err != nil {
		return nil, err
	}
	inner, err := w.items(r.Patterns)
	if err != nil {
		return nil, err
	}
	return append([]item{{match: r.End, scope: scope, captures: captures, pop: true}}, inner...), nil
}

// scopes splits TextMate captures into a sublime-syntax scope for the
// whole match, from a rule's name or capture 0, and the numbered groups.
func scopes(name string, captures map[string]capture) (string, map[string]string, error) {
	scope := name
	groups := map[string]string{}
	for key, c := range captures {
		if len(c.Patterns) > 0 {
			return "", nil, fmt.Errorf("capture %s holds patterns, which sublime-syntax cannot; give the rule a split", key)
		}
		if key == "0" {
			scope = c.Name
			continue
		}
		if c.Name != "" {
			groups[key] = c.Name
		}
	}
	return scope, groups, nil
}

func (it item) write(b *bytes.Buffer) {
	if it.include != "" {
		fmt.Fprintf(b, "    - include: %s\n", it.include)
		return
	}
	fmt.Fprintf(b, "    - match: %s\n", quote(it.match))
	if it.scope != "" {
		fmt.Fprintf(b, "      scope: %s\n", it.scope)
	}
	if len(it.captures) > 0 {
		b.WriteString("      captures:\n")
		keys := slices.SortedFunc(maps.Keys(it.captures), func(a, b string) int {
			x, _ := strconv.Atoi(a)
			y, _ := strconv.Atoi(b)
			return x - y
		})
		for _, k := range keys {
			fmt.Fprintf(b, "        %s: %s\n", k, it.captures[k])
		}
	}
	switch {
	case it.push != "":
		fmt.Fprintf(b, "      push: %s\n", it.push)
	case it.set != "":
		fmt.Fprintf(b, "      set: %s\n", it.set)
	case it.pop:
		b.WriteString("      pop: true\n")
	}
}

// quote is a YAML single-quoted scalar, in which only the quote itself is
// escaped, so a regex reads as written.
func quote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}
